def compile_query(table: str, filters: dict | None = None, joins: list[tuple[str, str, str]] | None = None) -> str:
    sql = f"SELECT * FROM {table}"
    if joins:
        for jt, lk, rk in joins:
            sql += f" INNER JOIN {jt} ON {table}.{lk} = {jt}.{rk}"
    if filters:
        clauses = [f"{k} = '{v}'" if isinstance(v, str) else f"{k} = {v}" for k, v in filters.items()]
        sql += " WHERE " + " AND ".join(clauses)
    return sql

