import unittest
from orm.compiler import compile_query

class TestCompiler(unittest.TestCase):
    def test_compile(self):
        q = compile_query("users", filters={"status": "active"}, joins=[("orders", "id", "user_id")])
        self.assertEqual(q, "SELECT * FROM users INNER JOIN orders ON users.id = orders.user_id WHERE status = 'active'")

if __name__ == '__main__': unittest.main()
